'use strict';
let installPrompt=null,pwaRegistration=null,pwaBusy=false,pwaMessage='',pwaUpdate=false;
const offlinePreference='antar-offline-enabled';
function offlineEnabled(){try{return localStorage.getItem(offlinePreference)==='yes'}catch{return false}}
function installedApp(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function installView(){return `<a class="back install-link" href="#home">‹ Home</a><h1>A little space.<br>On your home screen.</h1><p class="sub">Antar ko paas rakho. Open it like an app, whenever you need a moment.</p><div class="install-status" id="pwa-status" role="status">${esc(pwaMessage|| (installedApp()?'You’re using the app window.':offlineEnabled()?'Offline mode is enabled on this device.':'Install is optional. Antar also works in your browser.'))}</div><button class="primary pwa-action" data-pwa="install" ${installPrompt?'':'hidden'}>Install Antar</button><h2>On iPhone or iPad</h2><ol class="install-steps"><li>Open this site in <strong>Safari</strong> and sign in to Vercel if asked.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong> (you may need to scroll).</li><li>Keep <strong>Open as Web App</strong> on if shown, then tap <strong>Add</strong>.</li></ol><details><summary>On Android or a computer</summary><p class="sub">Use “Install Antar” above when available, or find “Install app” / “Add to Home screen” in your browser menu. Some in-app browsers do not support installation; open the link in Safari, Chrome, or Edge.</p></details><div class="divider"></div><h2>A little room, even offline.</h2><p class="sub">Download the app, all 60 excerpts, feeling words, and interactive stories. Full chapter readers become available after you open them online. PDFs and EPUBs need a connection or a separate download.</p><p class="note">Offline mode keeps app and reading content on this device, including after signing out of Vercel. Saved logs and anchors already stay in this browser. Anyone using this browser profile can access them. Installation may use separate storage on some phones; check your history before relying on it and keep an export.</p><button class="secondary" data-pwa="${offlineEnabled()?'disable':'enable'}" ${pwaBusy?'disabled':''}>${pwaBusy?'Preparing your offline space…':offlineEnabled()?'Remove offline app download':'Enable offline mode'}</button><p class="small">Removing the offline download keeps saved check-ins and anchors. Browser or device cleanup can still remove local data. Export important history from My month.</p><div class="divider"></div><h2>Keep Antar up to date</h2><p class="sub">Updates wait until you choose to reload. Save any open check-in or thought first.</p><button class="secondary pwa-action" data-pwa="update" ${pwaUpdate?'':'hidden'}>Update and reopen Antar</button><button class="text-btn" data-pwa="check">Check for app updates</button><p class="small">App version: skills-2</p>`}
function refreshPwa(){if(typeof route!=='undefined'&&route==='install')render(true)}
function showPwaMessage(message){pwaMessage=message;refreshPwa()}
function connectionStatus(){const banner=document.querySelector('#connection-banner');if(banner){banner.hidden=navigator.onLine;banner.textContent='You’re offline. Saved moments stay here; unopened full chapters may need a connection.'}}
function watchRegistration(reg){pwaRegistration=reg;pwaUpdate=!!reg.waiting;reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){pwaUpdate=true;refreshPwa()}})});}
async function enableOffline(){if(!('serviceWorker'in navigator))return showPwaMessage('This browser cannot prepare offline mode. Try Safari, Chrome, or Edge.');if(!navigator.onLine)return showPwaMessage('Connect to the internet to prepare the offline download.');pwaBusy=true;showPwaMessage('Downloading the app and excerpts. Keep this page open for a moment.');try{const reg=await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});watchRegistration(reg);await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('timeout')),45000))]);localStorage.setItem(offlinePreference,'yes');pwaMessage='Your offline space is ready. Full chapters are kept after you open them online.';}catch{pwaMessage='Offline download could not finish. Check your connection, sign-in, or free storage and try again.'}finally{pwaBusy=false;refreshPwa()}}
async function disableOffline(){try{for(const reg of await navigator.serviceWorker.getRegistrations())if(new URL(reg.scope).origin===location.origin)await reg.unregister();for(const key of await caches.keys())if(key.startsWith('antar-'))await caches.delete(key);localStorage.removeItem(offlinePreference);pwaRegistration=null;pwaUpdate=false;showPwaMessage('Offline download removed. Saved check-ins and anchors are unchanged. Reopen Antar online to finish.')}catch{showPwaMessage('The offline download could not be removed. Try again while online.')}}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;refreshPwa()});
window.addEventListener('appinstalled',()=>{installPrompt=null;showPwaMessage('Antar was added to your apps. You can enable offline mode separately.')});
window.addEventListener('online',connectionStatus);window.addEventListener('offline',connectionStatus);
document.addEventListener('click',async event=>{const action=event.target.closest('[data-pwa]')?.dataset.pwa;if(!action)return;if(action==='install'&&installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;refreshPwa()}if(action==='enable')await enableOffline();if(action==='disable')await disableOffline();if(action==='update'){if(!confirm('Saved entries stay here. Any unsaved writing or exercise changes will be lost. Reload now?'))return;const worker=pwaRegistration?.waiting;if(worker){navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});worker.postMessage({type:'ACTIVATE_UPDATE'})}else location.reload()}if(action==='check'){if(!navigator.onLine)return showPwaMessage('Connect to the internet to check for updates.');try{if(pwaRegistration){await pwaRegistration.update();pwaUpdate=!!pwaRegistration.waiting;showPwaMessage(pwaUpdate?'An update is ready. Save your work before reopening.':'Update check requested. If a new version is found, the update button will appear here.')}else showPwaMessage('Offline mode is off. Reopening Antar online loads the latest version.')}catch{showPwaMessage('Could not check for updates. Check your connection and Vercel sign-in.')}}});
window.addEventListener('load',()=>{connectionStatus();if(offlineEnabled()&&'serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(watchRegistration).catch(()=>{pwaMessage='Offline mode could not start. Reconnect and try enabling it again.';refreshPwa()});});
